<?php
error_reporting(E_ALL & ~E_NOTICE & ~E_WARNING);
?>
<?php
// salt_unionClass.php — Union headword index endpoint (A55v2, H6065).
//
// Serves the cross-dictionary UNION headword index over a self-contained,
// build-time data pair (no *.sqlite dependency):
//   api1/data/union_headwords.tsv   byte-sorted index: slp1 \t n \t code,code,...
//   api1/data/union_meta.json       members, versions (D4), counts, provenance
// regenerated by tools/build_union_index.py from live csl-orig v02.
//
// Modes:
//   (no key)        -> 200 meta envelope (the union_meta.json, served as the
//                      response body: index version, member dicts with their
//                      CDSL versions, per-dict headword counts, provenance).
//   key=<headword>  -> union membership lookup via fseek binary search (the
//                      TSV is byte-sorted; strcmp collation — see meta
//                      index_collation). 200 found / 404 not in union.
//
// Parameters:
//   key      headword in the `input` transliteration scheme
//   input    slp1 (default), deva, hk, roman, itrans, velthuis
//   output   optional output scheme for headword_output (deva, slp1, hk, roman)
//
// The codebase resolves require_once() paths relative to the repo root
// (salt_common.php precedent); parm.php loads the transcoder without any
// sqlite dependency.
chdir(dirname(__DIR__));
require_once('parm.php');

class SaltUnionClass {
  public $json;
  private $data_tsv;
  private $data_meta;

  public function __construct() {
    $json_flags = JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES;
    $this->data_tsv  = __DIR__ . '/data/union_headwords.tsv';
    $this->data_meta = __DIR__ . '/data/union_meta.json';

    if (!file_exists($this->data_tsv) || !file_exists($this->data_meta)) {
      http_response_code(500);
      $this->json = json_encode(array(
        'status' => 500,
        'error' => 'union index data files missing; run tools/build_union_index.py',
      ), $json_flags);
      return;
    }

    $keyin = isset($_REQUEST['key']) ? trim((string)$_REQUEST['key']) : '';
    if ($keyin === '') {
      // ---- meta mode: the index itself IS the response envelope ------------
      $meta = file_get_contents($this->data_meta);
      // re-encode sanity: invalid JSON on disk is a truthful 500, not a lie
      if (json_decode($meta) === null) {
        http_response_code(500);
        $this->json = json_encode(array(
          'status' => 500,
          'error' => 'union_meta.json is not valid JSON',
        ), $json_flags);
        return;
      }
      $this->json = $meta;
      return;
    }

    // ---- lookup mode -------------------------------------------------------
    // same character strip as Parm::init_inputs_key / salt_multidict
    $invalid = array('$', '#', '<', '>', '=', '(', ')', '"', '\\');
    $keyin = str_replace($invalid, '', $keyin);
    if ($keyin === '') {
      http_response_code(400);
      $this->json = json_encode(array(
        'status' => 400,
        'error' => "Invalid or empty 'key'",
      ), $json_flags);
      return;
    }

    $input = isset($_REQUEST['input']) ? $_REQUEST['input'] : 'slp1';
    // unknown schemes silently standardize to the slp1 default — same
    // behavior as salt_multidict / Parm (utilities/transcoder.php)
    $filterin = transcoder_standardize_filter($input);
    $slp1 = ($filterin === 'slp1')
      ? $keyin
      : transcoder_processString($keyin, $filterin, 'slp1');
    if ($slp1 === '') {
      http_response_code(400);
      $this->json = json_encode(array(
        'status' => 400,
        'error' => 'Empty key after transliteration',
      ), $json_flags);
      return;
    }

    $row = $this->binary_search($slp1);
    if ($row === null) {
      http_response_code(404);
      $this->json = json_encode(array(
        'status' => 404,
        'error' => 'headword not in union index',
        'key' => $slp1,
      ), $json_flags);
      return;
    }
    list($hit, $n, $codes) = $row;

    $out = array(
      'status' => 200,
      'key' => $keyin,
      'headword_slp1' => $hit,
      'n_dicts' => (int)$n,
      'dicts' => $codes,
    );
    if (isset($_REQUEST['output'])) {
      // same standardizer; unknown schemes fall back to slp1 (Parm default)
      $filterout = transcoder_standardize_filter($_REQUEST['output']);
      $out['headword_output'] = transcoder_processString($hit, 'slp1', $filterout);
    }
    $this->json = json_encode($out, $json_flags);
  }

  // fseek binary search over the byte-sorted TSV. Each probe backs up one
  // byte, discards the (possibly empty) partial line, then reads one whole
  // record — seeking to mid-1 guarantees a record starting exactly at mid is
  // read, not skipped. strcmp(needle, field) matches Python codepoint order
  // for the pure-ASCII SLP1 keys this index stores.
  private function binary_search($needle) {
    $fp = fopen($this->data_tsv, 'rb');
    if ($fp === false) { return null; }
    $size = filesize($this->data_tsv);
    $lo = 0;
    $hi = $size;
    while ($lo < $hi) {
      $mid = (int)(($lo + $hi) / 2);
      if ($mid > 0) {
        fseek($fp, $mid - 1);
        fgets($fp);                          // discard partial line
      } else {
        fseek($fp, 0);
      }
      $line = fgets($fp);
      if ($line === false) { $hi = $mid; continue; }
      $tab = strpos($line, "\t");
      if ($tab === false) { $hi = $mid; continue; }
      $field = rtrim(substr($line, 0, $tab), "\r\n");
      $cmp = strcmp($field, $needle);
      if ($cmp === 0) {
        fclose($fp);
        $rest = rtrim(substr($line, $tab + 1), "\r\n");
        $parts = explode("\t", $rest, 2);
        return array($field, $parts[0], explode(',', $parts[1]));
      }
      if ($cmp < 0) {
        $lo = ftell($fp);
      } else {
        $hi = $mid;
      }
    }
    fclose($fp);
    return null;
  }
}
?>
